CREATE FUNCTION public.zveltio_collection_allows(coll text, act text) RETURNS boolean
    LANGUAGE plpgsql STABLE PARALLEL SAFE
    AS $_$
DECLARE
  actor boolean := coalesce(current_setting('zveltio.actor', true), '') = 'on';
  sys text := coalesce(current_setting('zveltio.system_collections', true), '');
  g text;
BEGIN
  IF act = 'read'
     AND lower(coalesce(nullif(current_setting('zveltio.rls_bypass', true), ''), 'off')) IN ('on', 'true', '1') THEN
    RETURN true;
  END IF;
  IF sys <> '' AND (strpos(sys, ',' || coll || ',') > 0 OR strpos(sys, ',*,') > 0) THEN
    RETURN true;
  END IF;
  IF actor THEN
    IF coalesce(current_setting('zveltio.collection_all', true), '') = 'on' THEN
      RETURN true;
    END IF;
    g := coalesce(current_setting('zveltio.collection_grants', true), '');
    IF strpos(g, ',' || coll || ':' || act || ',') > 0
       OR strpos(g, ',' || coll || ':*,') > 0
       OR strpos(g, ',*:' || act || ',') > 0 THEN
      RETURN true;
    END IF;
  END IF;
  -- Below: the two that look at the ROLE, asked last because they cost most.
  IF current_user::text ~ '^zveltio_(ext|extb|wrk)(_|$)' OR current_user::text = 'zveltio_worker' THEN
    RETURN EXISTS (
      SELECT 1 FROM pg_roles r
       WHERE r.rolname = 'zveltio_coll_exempt'
         AND pg_has_role(current_user, r.oid, 'USAGE')
    );
  END IF;
  RETURN NOT actor;
END
$_$;

CREATE FUNCTION public.zveltio_drop_deleted_user_grants() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  DELETE FROM public.zvd_permissions WHERE ptype IN ('g', 'p') AND v0 = OLD.id;
  RETURN OLD;
END;
$$;

CREATE FUNCTION public.zveltio_drop_removed_member_grants() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.zv_tenant_users
                  WHERE tenant_id = OLD.tenant_id AND user_id = OLD.user_id) THEN
    DELETE FROM public.zvd_permissions
     WHERE ptype = 'g' AND v0 = OLD.user_id AND v2 = OLD.tenant_id::text;
  END IF;
  RETURN NULL;
END;
$$;

CREATE FUNCTION public.zveltio_grant_member_role() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO public.zvd_permissions (ptype, v0, v1, v2)
  VALUES ('g', NEW.id, 'member', '*')
  ON CONFLICT DO NOTHING;
  RETURN NULL;
END;
$$;

CREATE FUNCTION public.zveltio_one_god_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  other_god text;
BEGIN
  IF NEW.role IS DISTINCT FROM 'god' THEN
    RETURN NEW;
  END IF;
  -- An UPDATE that leaves an existing god a god is not a second god.
  IF TG_OP = 'UPDATE' AND OLD.role = 'god' THEN
    RETURN NEW;
  END IF;

  SELECT id INTO other_god FROM "user" WHERE role = 'god' AND id <> NEW.id LIMIT 1;
  IF other_god IS NOT NULL THEN
    RAISE EXCEPTION
      'this instance already has a god (%): there is exactly one, and it is the account that installs extensions and may act in any firm. Demote it first, or grant this user a per-firm administrator role instead.',
      other_god
      USING ERRCODE = 'unique_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.zveltio_sync_tombstone() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    SET "zveltio.current_tenant" TO ''
    AS $$
DECLARE
  t uuid;
BEGIN
  FOR t IN SELECT DISTINCT tenant_id FROM zv_old_rows LOOP
    PERFORM set_config('zveltio.current_tenant', t::text, true);
    INSERT INTO zv_sync_tombstones (tenant_id, collection, row_id)
      SELECT tenant_id, TG_TABLE_NAME, id FROM zv_old_rows WHERE tenant_id = t;
  END LOOP;
  RETURN NULL;
END $$;

CREATE FUNCTION public.zveltio_tenant_ancestors(node uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  WITH RECURSIVE walk(id, parent_id, depth) AS (
    SELECT t.id, t.parent_id, 0 FROM zv_tenants t WHERE t.id = node
    UNION ALL
    SELECT p.id, p.parent_id, w.depth + 1
      FROM zv_tenants p JOIN walk w ON p.id = w.parent_id
     WHERE w.depth < 64
  )
  SELECT id FROM walk WHERE id <> node
$$;

CREATE FUNCTION public.zveltio_tenant_no_cycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  walker uuid;
  depth  int := 0;
BEGIN
  IF NEW.parent_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.parent_id = NEW.id THEN
    RAISE EXCEPTION 'tenant % cannot be its own parent', NEW.id;
  END IF;
  walker := NEW.parent_id;
  WHILE walker IS NOT NULL LOOP
    depth := depth + 1;
    IF depth > 64 THEN
      RAISE EXCEPTION 'tenant hierarchy deeper than 64 levels at %, refusing', NEW.id;
    END IF;
    IF walker = NEW.id THEN
      RAISE EXCEPTION 'tenant % would form a parent cycle', NEW.id;
    END IF;
    SELECT parent_id INTO walker FROM zv_tenants WHERE id = walker;
  END LOOP;
  RETURN NEW;
END $$;

CREATE FUNCTION public.zveltio_tenant_reach(p_user text, p_tenant text, OUT visible_csv text, OUT ancestors_csv text) RETURNS record
    LANGUAGE plpgsql STABLE PARALLEL SAFE
    AS $$
DECLARE
  v_tenant uuid := p_tenant::uuid;
  v_total int;
  v_live int;
  v_widest int;
  v_set text[];
BEGIN
  SELECT coalesce(string_agg(a::text, ','), '')
    INTO ancestors_csv
    FROM zveltio_tenant_ancestors(v_tenant) AS a
   WHERE a IS NOT NULL;

  SELECT count(*),
         count(*) FILTER (WHERE u.valid_from <= now() AND (u.valid_to IS NULL OR u.valid_to > now())),
         coalesce(max(CASE u.read_scope WHEN 'org' THEN 3 WHEN 'subtree' THEN 2
                                        WHEN 'list' THEN 1 ELSE 0 END)
                  FILTER (WHERE u.valid_from <= now() AND (u.valid_to IS NULL OR u.valid_to > now())), 0)
    INTO v_total, v_live, v_widest
    FROM zv_tenant_users u
   WHERE u.user_id = p_user AND u.tenant_id = v_tenant;

  IF v_total = 0 THEN
    visible_csv := NULL;
    RETURN;
  END IF;
  IF v_live = 0 THEN
    visible_csv := '00000000-0000-0000-0000-000000000000';
    RETURN;
  END IF;

  IF v_widest = 3 THEN
    SELECT coalesce(string_agg(t.id::text, ','), '') INTO visible_csv FROM zv_tenants t;
    RETURN;
  ELSIF v_widest = 2 THEN
    v_set := ARRAY(SELECT s::text FROM zveltio_tenant_subtree(v_tenant) AS s);
  ELSIF v_widest = 1 THEN
    v_set := ARRAY(
      SELECT e::text
        FROM zv_tenant_users l, unnest(l.scope_list) AS e
       WHERE l.user_id = p_user AND l.tenant_id = v_tenant AND l.read_scope = 'list'
         AND l.valid_from <= now() AND (l.valid_to IS NULL OR l.valid_to > now())
    );
  ELSE
    visible_csv := p_tenant;
    RETURN;
  END IF;

  -- First occurrence wins, so the own unit stays first.
  SELECT string_agg(z.id, ',' ORDER BY z.o)
    INTO visible_csv
    FROM (
      SELECT x.id, min(x.o) AS o
        FROM unnest(ARRAY[p_tenant] || v_set) WITH ORDINALITY AS x(id, o)
       WHERE x.id IS NOT NULL AND x.id <> ''
       GROUP BY x.id
    ) z;
END;
$$;

COMMENT ON FUNCTION public.zveltio_tenant_reach(p_user text, p_tenant text, OUT visible_csv text, OUT ancestors_csv text) IS 'The read reach of a user in a unit, as the GUC spelling: visible_csv (NULL = publish no set) and ancestors_csv. Called by withTenantIsolation before it drops to zveltio_rls.';

CREATE FUNCTION public.zveltio_tenant_scope_ok(row_tenant text) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT row_tenant = ANY (zveltio_visible_tenants_text())
$$;

COMMENT ON FUNCTION public.zveltio_tenant_scope_ok(row_tenant text) IS 'TEXT overload of zveltio_tenant_scope_ok(uuid). Same fail-closed opt-in. See 047.';

CREATE FUNCTION public.zveltio_tenant_scope_ok(row_tenant uuid) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT row_tenant = ANY (zveltio_visible_tenants())
$$;

COMMENT ON FUNCTION public.zveltio_tenant_scope_ok(row_tenant uuid) IS 'Compatibility spelling of `tenant_id = ANY(zveltio_visible_tenants())`, for extension migrations that name it. Correct but not indexable — the boot reconciler rewrites policies onto the ANY form. See migration 003.';

CREATE FUNCTION public.zveltio_tenant_scope_ok(row_tenant text, inherit_down boolean) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT row_tenant = ANY (zveltio_visible_tenants_text())
      OR (inherit_down AND row_tenant = ANY (zveltio_ancestor_tenants_text()))
$$;

CREATE FUNCTION public.zveltio_tenant_scope_ok(row_tenant uuid, inherit_down boolean) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT row_tenant = ANY (zveltio_visible_tenants())
      OR (inherit_down AND row_tenant = ANY (zveltio_ancestor_tenants()))
$$;

CREATE FUNCTION public.zveltio_tenant_subtree(root uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  WITH RECURSIVE walk(id, depth) AS (
    SELECT t.id, 0 FROM zv_tenants t WHERE t.id = root
    UNION ALL
    SELECT c.id, w.depth + 1
      FROM zv_tenants c JOIN walk w ON c.parent_id = w.id
     WHERE w.depth < 64
  )
  SELECT id FROM walk
$$;

COMMENT ON FUNCTION public.zveltio_tenant_subtree(root uuid) IS 'The unit and everything under it. Depth-capped at 64 as a second line behind the cycle trigger — a recursive walk over a cycle does not fail, it hangs.';

CREATE FUNCTION public.zveltio_tenant_write_ok(row_tenant text) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN NULLIF(current_setting('zveltio.current_tenant', true), '') IS NOT NULL THEN
      row_tenant = NULLIF(current_setting('zveltio.current_tenant', true), '')
    WHEN lower(coalesce(nullif(current_setting('zveltio.fail_closed_tenant', true), ''), 'off'))
         IN ('on', 'true', '1') THEN
      false
    ELSE
      row_tenant = '00000000-0000-0000-0000-000000000001'
  END
  AND NULLIF(current_setting('zveltio.visible_tenants', true), '')
      IS DISTINCT FROM '00000000-0000-0000-0000-000000000000'
$$;

CREATE FUNCTION public.zveltio_tenant_write_ok(row_tenant uuid) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN NULLIF(current_setting('zveltio.current_tenant', true), '') IS NOT NULL THEN
      row_tenant = NULLIF(current_setting('zveltio.current_tenant', true), '')::uuid
    WHEN lower(coalesce(nullif(current_setting('zveltio.fail_closed_tenant', true), ''), 'off'))
         IN ('on', 'true', '1') THEN
      false
    ELSE
      row_tenant = '00000000-0000-0000-0000-000000000001'::uuid
  END
  AND NULLIF(current_setting('zveltio.visible_tenants', true), '')
      IS DISTINCT FROM '00000000-0000-0000-0000-000000000000'
$$;

COMMENT ON FUNCTION public.zveltio_tenant_write_ok(row_tenant uuid) IS 'Row WRITE permission: the own node only. Data belong to the subordinate; a level above reads and approves, it does not correct in another''s place.';

CREATE FUNCTION public.zveltio_user_ban_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.banned IS NOT TRUE THEN
    NEW.ban_source := NULL;
    NEW.banned_at := NULL;
  ELSE
    NEW.ban_source := COALESCE(NEW.ban_source, 'unknown');
    IF TG_OP = 'INSERT' OR OLD.banned IS NOT TRUE THEN
      NEW.banned_at := COALESCE(NEW.banned_at, now());
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public.zveltio_visible_tenants() RETURNS uuid[]
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN NULLIF(current_setting('zveltio.visible_tenants', true), '') IS NOT NULL THEN
      string_to_array(current_setting('zveltio.visible_tenants', true), ',')::uuid[]
    WHEN NULLIF(current_setting('zveltio.current_tenant', true), '') IS NOT NULL THEN
      ARRAY[NULLIF(current_setting('zveltio.current_tenant', true), '')::uuid]
    WHEN lower(coalesce(nullif(current_setting('zveltio.fail_closed_tenant', true), ''), 'off'))
         IN ('on', 'true', '1') THEN
      ARRAY[]::uuid[]
    ELSE
      ARRAY['00000000-0000-0000-0000-000000000001'::uuid]
  END
$$;

COMMENT ON FUNCTION public.zveltio_visible_tenants() IS 'The units the current transaction may READ, as an array so a policy can be written as an indexable `tenant_id = ANY(...)`. Falls back to the 029 current_tenant equality and the 047 fail-closed opt-in when the middleware published no set — which is every background worker and every single-tenant install, and is why this migration is invisible to them.';

CREATE FUNCTION public.zveltio_visible_tenants_text() RETURNS text[]
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN NULLIF(current_setting('zveltio.visible_tenants', true), '') IS NOT NULL THEN
      string_to_array(current_setting('zveltio.visible_tenants', true), ',')
    WHEN NULLIF(current_setting('zveltio.current_tenant', true), '') IS NOT NULL THEN
      ARRAY[NULLIF(current_setting('zveltio.current_tenant', true), '')]
    WHEN lower(coalesce(nullif(current_setting('zveltio.fail_closed_tenant', true), ''), 'off'))
         IN ('on', 'true', '1') THEN
      ARRAY[]::text[]
    ELSE
      ARRAY['00000000-0000-0000-0000-000000000001']
  END
$$;

SET LOCAL default_tablespace = '';

SET LOCAL default_table_access_method = heap;

CREATE TABLE public.account (
    id text NOT NULL,
    "accountId" text NOT NULL,
    "providerId" text NOT NULL,
    "userId" text NOT NULL,
    "accessToken" text,
    "refreshToken" text,
    "idToken" text,
