    "refreshTokenExpiresAt" timestamp with time zone,
    scope text,
    password text,
    "createdAt" timestamp with time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT now() NOT NULL,
    issuer text
);

COMMENT ON COLUMN public.account.issuer IS 'Who vouched for this identity. Better Auth 1.7 writes `local:credential` for password accounts and the provider''s issuer for OAuth ones, and matches on it at sign-in — a NULL here means the account cannot log in.';

