CREATE TABLE public.zv_edge_functions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    display_name text NOT NULL,
    description text,
    code text DEFAULT ''::text NOT NULL,
    runtime text DEFAULT 'bun'::text NOT NULL,
    http_method text DEFAULT 'POST'::text NOT NULL,
    path text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    timeout_ms integer DEFAULT 30000 NOT NULL,
    env_vars jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    tenant_id uuid DEFAULT COALESCE((NULLIF(current_setting('zveltio.current_tenant'::text, true), ''::text))::uuid, '00000000-0000-0000-0000-000000000001'::uuid),
    egress text[],
    CONSTRAINT zv_edge_functions_egress_check CHECK (((egress IS NULL) OR (cardinality(egress) = 0) OR ((array_ndims(egress) = 1) AND (array_lower(egress, 1) = 1) AND (cardinality(string_to_array(array_to_string(egress, ','::text, ''::text), ','::text)) = cardinality(egress)) AND (array_to_string(egress, ','::text, ''::text) ~ '^(\[[0-9a-f:.]+\]|[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*)(:[0-9]{1,5})?(,(\[[0-9a-f:.]+\]|[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*)(:[0-9]{1,5})?)*$'::text))))
);

