    to_tenant uuid NOT NULL,
    moved_at timestamp with time zone DEFAULT now() NOT NULL,
    moved_by text,
    reason text
);

COMMENT ON TABLE public.zv_tenant_transfers IS 'Journal of records moved between units. Not full temporal ownership — that would need columns on all 48 tenant tables — but it answers "who held this file in March", and it does not stand in the way of the fuller version.';

CREATE TABLE public.zv_tenant_users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    user_id text NOT NULL,
    role text DEFAULT 'member'::text NOT NULL,
    invited_by text,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    read_scope text DEFAULT 'self'::text NOT NULL,
    scope_list uuid[],
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    CONSTRAINT zv_tenant_users_read_scope_check CHECK ((read_scope = ANY (ARRAY['self'::text, 'subtree'::text, 'list'::text, 'org'::text]))),
    CONSTRAINT zv_tenant_users_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'admin'::text, 'member'::text, 'viewer'::text]))),
    CONSTRAINT zv_tenant_users_scope_list_check CHECK ((((read_scope = 'list'::text) AND (scope_list IS NOT NULL) AND (cardinality(scope_list) > 0)) OR ((read_scope <> 'list'::text) AND (scope_list IS NULL))))
);

COMMENT ON COLUMN public.zv_tenant_users.read_scope IS 'How far this assignment can READ: self | subtree | list | org. Writing has no reach — see zveltio_tenant_write_ok.';

COMMENT ON COLUMN public.zv_tenant_users.valid_to IS 'NULL = open-ended. Revocation is a date, so it needs no retelling elsewhere.';

CREATE TABLE public.zv_tenants (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    settings jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    parent_id uuid,
    closed_at timestamp with time zone,
    merged_into uuid,
    CONSTRAINT zv_tenants_status_check CHECK ((status = ANY (ARRAY['active'::text, 'suspended'::text, 'deleted'::text])))
);

COMMENT ON COLUMN public.zv_tenants.parent_id IS 'Parent unit. NULL = a root. Depth is arbitrary.';

COMMENT ON COLUMN public.zv_tenants.closed_at IS 'A unit is never deleted. Dissolution sets this; historical rows keep pointing at a node that still exists.';

COMMENT ON COLUMN public.zv_tenants.merged_into IS 'Where this unit''s work continued after closure. Read with closed_at.';

