CREATE TABLE public.zvd_collections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    display_name text,
    icon text DEFAULT 'Table'::text,
    route_group text DEFAULT 'private'::text,
    is_permissioned boolean DEFAULT true,
    sort integer DEFAULT 99,
    singular_name text,
    description text,
    fields jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_type text DEFAULT 'table'::text NOT NULL,
    virtual_config jsonb,
    is_managed boolean DEFAULT true NOT NULL,
    is_system boolean DEFAULT false NOT NULL,
    schema_locked boolean DEFAULT false NOT NULL,
    has_trgm boolean DEFAULT false NOT NULL,
    inherit_down boolean DEFAULT false NOT NULL,
    CONSTRAINT zvd_collections_route_group_check CHECK ((route_group = ANY (ARRAY['public'::text, 'partners'::text, 'private'::text, 'admin'::text]))),
    CONSTRAINT zvd_collections_source_type_check CHECK ((source_type = ANY (ARRAY['table'::text, 'virtual'::text])))
);

COMMENT ON COLUMN public.zvd_collections.source_type IS 'collection = created by Zveltio, table = introspected BYOD';

COMMENT ON COLUMN public.zvd_collections.virtual_config IS 'VirtualConfig JSON: source_url, auth_type, auth_value, field_mapping, list_path, id_field';

COMMENT ON COLUMN public.zvd_collections.is_managed IS 'false = BYOD table, Zveltio will NOT alter schema';

COMMENT ON COLUMN public.zvd_collections.is_system IS 'true for engine-shipped core collections';

COMMENT ON COLUMN public.zvd_collections.schema_locked IS 'true blocks removing columns (ADD still allowed)';

COMMENT ON COLUMN public.zvd_collections.inherit_down IS 'Rows written at an ancestor unit are readable from below. Off by default: head-office payroll does not become county-visible merely by sitting higher. Upward visibility is NOT a per-collection flag — it is governed by read_scope on the assignment and by Casbin on the resource.';

