);

COMMENT ON TABLE public.zvd_permissions_pruned_012 IS 'Role grants removed by migration 012 because no membership supported them. Kept so the deletion is reversible and auditable; safe to drop once reviewed.';

CREATE TABLE public.zvd_permissions_pruned_033 (
    id uuid NOT NULL,
    ptype text NOT NULL,
    v0 text,
    v1 text,
    v2 text,
    v3 text,
    v4 text,
    v5 text,
