    column_role text,
    pruned_at timestamp with time zone DEFAULT now() NOT NULL
);

COMMENT ON TABLE public.zvd_permissions_pruned_033 IS 'Casbin g rows that mirrored "user".role, removed by migration 033 once the column became the only source. Kept so the deletion is reversible and auditable; safe to drop once reviewed.';

CREATE TABLE public.zvd_permissions_pruned_034 (
    id uuid NOT NULL,
    ptype text NOT NULL,
    v0 text,
    v1 text,
    v2 text,
    v3 text,
    v4 text,
    v5 text,
    created_at timestamp with time zone,
    pruned_at timestamp with time zone DEFAULT now() NOT NULL
);

COMMENT ON TABLE public.zvd_permissions_pruned_034 IS 'Tenant-domain role grants of users with no membership in that tenant, removed by migration 034. Kept so the deletion is reversible and auditable; safe to drop once reviewed.';

