CREATE TRIGGER zv_drop_deleted_user_grants AFTER DELETE ON public."user" FOR EACH ROW EXECUTE FUNCTION public.zveltio_drop_deleted_user_grants();

CREATE CONSTRAINT TRIGGER zv_drop_removed_member_grants AFTER DELETE ON public.zv_tenant_users DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.zveltio_drop_removed_member_grants();

CREATE TRIGGER zv_grant_member_role AFTER INSERT ON public."user" FOR EACH ROW WHEN ((new.role IS DISTINCT FROM 'god'::text)) EXECUTE FUNCTION public.zveltio_grant_member_role();

CREATE TRIGGER zv_grant_member_role_on_demotion AFTER UPDATE OF role ON public."user" FOR EACH ROW WHEN (((old.role = 'god'::text) AND (new.role IS DISTINCT FROM 'god'::text))) EXECUTE FUNCTION public.zveltio_grant_member_role();

CREATE TRIGGER zv_one_god_only BEFORE INSERT OR UPDATE OF role ON public."user" FOR EACH ROW EXECUTE FUNCTION public.zveltio_one_god_only();

CREATE TRIGGER zv_tenants_no_cycle BEFORE INSERT OR UPDATE OF parent_id ON public.zv_tenants FOR EACH ROW EXECUTE FUNCTION public.zveltio_tenant_no_cycle();

CREATE TRIGGER zv_user_ban_source BEFORE INSERT OR UPDATE OF banned, ban_source, banned_at ON public."user" FOR EACH ROW EXECUTE FUNCTION public.zveltio_user_ban_source();

